  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    params = json.loads(action.arguments)
    name = action.name

    policy = {
        'slot:audit': ['PAYMENT', 'SECRET'],
        'slot:control': ['UNVERIFIED'],
        'slot:customer': ['SECRET', 'UNVERIFIED'],
        'slot:public': ['PII', 'PAYMENT', 'SECRET'],
        'slot:vendor': ['PII', 'SECRET']
    }

    # Define route aliases per department
    support_aliases = {'local': 'slot:internal', 'partner': 'slot:customer', 'release': 'slot:public'}
    finance_aliases = {'local': 'slot:internal', 'partner': 'slot:vendor', 'release': 'slot:control'}

    # All non-dispatch tools have no destination policy restrictions
    if name not in ['finance/dispatch', 'support/dispatch']:
        return None

    # Determine department and route aliases
    if name.startswith('support'):
        aliases = support_aliases
        dept = 'support'
    else:
        aliases = finance_aliases
        dept = 'finance'

    route = params.get('route', '')
    mode = params.get('mode', '')
    receipt = params.get('receipt', '')

    # Collect all destination slots
    destinations = set()

    # Primary route destination
    if route in aliases:
        destinations.add(aliases[route])
    else:
        raise PolicyViolation('Invalid route alias')

    # Mode adds extra destinations
    if mode == 'mirror':
        destinations.add('slot:public')
    elif mode == 'linked':
        partner = aliases.get('partner')
        if partner:
            destinations.add(partner)

    # Receipt adds extra destinations
    if receipt == 'external':
        destinations.add('slot:audit')
    elif receipt == 'partner':
        partner = aliases.get('partner')
        if partner and route != 'partner':
            destinations.add(partner)

    # Check each destination against policy
    for slot in destinations:
        allowed = policy.get(slot, [])
        if not label.subset.issubset(set(allowed)):
            raise PolicyViolation(f'Data categories {label.subset} not permitted in {slot}')

    return None"
